def attach_particle(word: str, particle: str) -> str:
    DIG = ['영', '일', '이', '삼', '사', '오', '육', '칠', '팔', '구']
    GROUP = ['', '만', '억', '조', '경']
    PLACE = ['', '십', '백', '천']

    def last_syllable(w):
        if w and w[-1].isdigit():
            # Collect trailing digit run
            j = len(w)
            while j > 0 and w[j - 1].isdigit():
                j -= 1
            n = int(w[j:])
            if n == 0:
                return '영'
            d = n % 10
            if d != 0:
                return DIG[d]
            # trailing zeros: find position of lowest nonzero digit
            p = 0
            m = n
            while m % 10 == 0:
                m //= 10
                p += 1
            if p % 4 == 0:
                return GROUP[p // 4]
            return PLACE[p % 4]
        return w[-1]

    def has_batchim(ch):
        code = ord(ch)
        if not (0xAC00 <= code <= 0xD7A3):
            return False
        return (code - 0xAC00) % 28 != 0

    def is_rieul(ch):
        code = ord(ch)
        if not (0xAC00 <= code <= 0xD7A3):
            return False
        return (code - 0xAC00) % 28 == 8

    last = last_syllable(word)
    consonant_form, vowel_form = particle.split('/')

    if particle == '으로/로':
        if not has_batchim(last) or is_rieul(last):
            chosen = vowel_form
        else:
            chosen = consonant_form
    else:
        chosen = consonant_form if has_batchim(last) else vowel_form

    return word + chosen
